import unittest
from codec import unsigned_varint_batch as core
from codec import unsigned_varint_batch_api as api

class OrdinaryTests(unittest.TestCase):
    def test_ordinary_0(self):
        self.assertEqual(core.encode_unsigned(0),b"\x00")

    def test_ordinary_1(self):
        self.assertEqual(core.encode_unsigned(1),b"\x01")

    def test_ordinary_2(self):
        self.assertEqual(core.encode_unsigned(127),b"\x7f")

    def test_ordinary_3(self):
        self.assertEqual(api.encode_values([]),b"")

    def test_ordinary_4(self):
        self.assertEqual(api.encode_values([1,2]),b"\x01\x02")
